descriptor.controllerScript:
self.onInit = function () {
  // ✅ Tailwind injection
  if (!document.getElementById('tailwindcss')) {
    const script = document.createElement('script');
    script.src = 'https://cdn.tailwindcss.com';
    script.id = 'tailwindcss';
    script.onload = () => self.ctx.detectChanges();
    document.head.appendChild(script);
  }

  // Init values
  self.cpu_usage = 'N/A';
  self.cpu_usage_raw = 'N/A';
  self.cpu_usage_ts = '';
  self.cpu_flash = false;

  self.device_temperature = 'N/A';
  self.device_temperature_raw = 'N/A';
  self.device_temperature_ts = '';
  self.temp_flash = false;

  self.debug_alias = 'Unknown';
  self.debug_entityName = 'Unknown';

  function formatTime(ts) {
    return new Date(ts).toLocaleTimeString();
  }

  function flash(key, duration = 500) {
    self[key] = true;
    setTimeout(() => {
      self[key] = false;
      self.ctx.detectChanges();
    }, duration);
  }

  self.onDataUpdated = function () {
    const aliases = self.ctx.$scope.ctx.aliasController.getEntityAliases();
    const firstAliasKey = Object.keys(aliases)[0];
    const entity = aliases[firstAliasKey]?.currentEntity;

    if (entity) {
      self.debug_alias = firstAliasKey;
      self.debug_entityName = entity.name;
    }

    self.ctx.data.forEach(dp => {
      const key = dp.dataKey.name;
      const latest = dp.data.at(-1);
      if (!latest) return;

      const [ts, raw] = latest;
      const val = parseFloat(raw);

      if (key === 'cpu_usage') {
        const newVal = (val * 100).toFixed(2);
        if (self.cpu_usage !== newVal) flash('cpu_flash');
        self.cpu_usage = newVal;
        self.cpu_usage_raw = raw;
        self.cpu_usage_ts = formatTime(ts);
      }

      if (key === 'device_temperature') {
        const newVal = val.toFixed(2);
        if (self.device_temperature !== newVal) flash('temp_flash');
        self.device_temperature = newVal;
        self.device_temperature_raw = raw;
        self.device_temperature_ts = formatTime(ts);
      }
    });

    self.ctx.detectChanges();
  };
};

